<?php
declare(strict_types=1);
function reply($data,int $status=200):never{http_response_code($status);header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store');echo json_encode($data,JSON_UNESCAPED_UNICODE|JSON_INVALID_UTF8_SUBSTITUTE);exit;}
function bad(string $message,int $status=400):never{throw new RuntimeException($message,$status);}
function txt($v,int $max=3000):string{return is_string($v)?mb_substr(trim($v),0,$max):'';}
function uid():string{return bin2hex(random_bytes(16));}
function nowms():int{return (int)floor(microtime(true)*1000);}
function stamp():string{return gmdate('Y-m-d\TH:i:s.000\Z');}
function query(string $sql,array $p=[]):PDOStatement{global $db;$s=$db->prepare($sql);$s->execute($p);return $s;}
function one(string $sql,array $p=[]){return query($sql,$p)->fetch(PDO::FETCH_ASSOC)?:null;}
function many(string $sql,array $p=[]):array{return query($sql,$p)->fetchAll(PDO::FETCH_ASSOC);}
function signedin():void{global $user;if(!$user)bad('Войдите в аккаунт',401);}
function admin():void{global $user;signedin();if($user['role']!=='admin')bad('Доступ только для команды',403);}
function rate(string $type,int $limit):void{$key=$type.':'.($_SERVER['REMOTE_ADDR']??'local');$t=nowms();query('INSERT INTO attempts(key,count,expires) VALUES (?,1,?) ON CONFLICT(key) DO UPDATE SET count=CASE WHEN expires<? THEN 1 ELSE count+1 END, expires=CASE WHEN expires<? THEN excluded.expires ELSE expires END',[$key,$t+900000,$t,$t]);if(one('SELECT count FROM attempts WHERE key=?',[$key])['count']>$limit)bad('Слишком много попыток. Попробуйте через 15 минут',429);}
try{
 $db=new PDO('sqlite:'.$private.'/data.sqlite',null,null,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_TIMEOUT=>10]);$db->exec('PRAGMA foreign_keys=ON');$db->exec('PRAGMA busy_timeout=10000');
 if(!one("SELECT name FROM sqlite_master WHERE name='users'")){$lock=fopen($private.'/schema.lock','c');flock($lock,LOCK_EX);if(!one("SELECT name FROM sqlite_master WHERE name='users'")){$db->beginTransaction();$db->exec(file_get_contents($private.'/schema.sql'));$db->commit();chmod($private.'/data.sqlite',0600);}flock($lock,LOCK_UN);fclose($lock);}
 $method=$_SERVER['REQUEST_METHOD'];$path=parse_url($_SERVER['REQUEST_URI'],PHP_URL_PATH);$body=[];
 if(!in_array($method,['GET','HEAD'],true)){
  if(!str_contains($_SERVER['CONTENT_TYPE']??'','application/json'))bad('Ожидается JSON',415);
  $origin=$_SERVER['HTTP_ORIGIN']??'';if($origin&&$origin!==$config['origin'])bad('Недопустимый источник запроса',403);
  $raw=file_get_contents('php://input',false,null,0,20001);if(strlen($raw)>20000)bad('Запрос слишком большой',413);$body=json_decode($raw,true);if(!is_array($body))bad('Некорректный запрос');
 }
 $cookie=$_COOKIE['ot_session']??'';$user=$cookie?one('SELECT u.id,u.name,u.email,u.role FROM users u JOIN sessions s ON u.id=s.user_id WHERE s.token=? AND s.expires>?',[hash('sha256',$cookie),nowms()]):null;
 if($path==='/api/me')reply(['user'=>$user]);
 if($path==='/api/health')reply(['ok'=>true,'storage'=>'sqlite','release'=>basename($release)]);
 if($path==='/api/admin/claim'&&$method==='POST'){signedin();rate('admin',5);if(!is_string($body['key']??null)||!hash_equals($config['admin_key'],$body['key']))bad('Неверный ключ настройки',403);$db->beginTransaction();if(one("SELECT id FROM users WHERE role='admin' LIMIT 1"))bad('Администратор уже назначен',409);query("UPDATE users SET role='admin' WHERE id=?",[$user['id']]);$db->commit();reply(['ok'=>true]);}
 if($path==='/api/content'&&$method==='GET'){$c=one('SELECT data FROM content WHERE id=?',['public']);reply($c?json_decode($c['data']):['projects'=>[],'prices'=>(object)[],'contacts'=>(object)[]]);}
 if($path==='/api/content'&&$method==='PUT'){admin();if(!is_array($body['projects']??null)||count($body['projects'])>30)bad('Некорректные проекты');foreach($body['projects'] as $p)foreach(['url','image'] as $key)if(!empty($p[$key])&&(!is_string($p[$key])||!str_starts_with($p[$key],'https://')))bad('Ссылки должны начинаться с https://');query('INSERT INTO content(id,data) VALUES (?,?) ON CONFLICT(id) DO UPDATE SET data=excluded.data',['public',json_encode($body,JSON_UNESCAPED_UNICODE)]);reply(['ok'=>true]);}
 if($path==='/api/register'&&$method==='POST'){rate('auth',15);$name=txt($body['name']??'',80);$email=strtolower(txt($body['email']??'',200));$pass=$body['password']??null;if(!$name||!filter_var($email,FILTER_VALIDATE_EMAIL)||!is_string($pass)||mb_strlen($pass)<10||mb_strlen($pass)>128)bad('Укажите имя, почту и пароль от 10 до 128 символов');if(empty($body['consent']))bad('Необходимо согласие на обработку данных');if(one('SELECT id FROM users WHERE email=?',[$email]))bad('Не удалось зарегистрироваться с этой почтой');$salt=uid();query('INSERT INTO users(id,name,email,password,salt,created) VALUES (?,?,?,?,?,?)',[uid(),$name,$email,hash_pbkdf2('sha256',$pass,$salt,100000,64),$salt,stamp()]);reply(['ok'=>true]);}
 if($path==='/api/login'&&$method==='POST'){rate('auth',15);$u=one('SELECT * FROM users WHERE email=?',[strtolower(txt($body['email']??'',200))]);$pass=is_string($body['password']??null)?$body['password']:'';$hashed=hash_pbkdf2('sha256',$pass,$u['salt']??'invalid',100000,64);if(!$u||!hash_equals($u['password'],$hashed))bad('Неверная почта или пароль',401);$token=bin2hex(random_bytes(48));query('INSERT INTO sessions(token,user_id,expires) VALUES (?,?,?)',[hash('sha256',$token),$u['id'],nowms()+604800000]);setcookie('ot_session',$token,['expires'=>time()+604800,'path'=>'/','secure'=>str_starts_with($config['origin'],'https:'),'httponly'=>true,'samesite'=>'Lax']);reply(['ok'=>true]);}
