 if($path==='/api/leads'&&$method==='POST'){rate('leads',10);$name=txt($body['name']??'',80);$contact=txt($body['contact']??'',200);$service=txt($body['service']??'',100);$description=txt($body['description']??'',5000);if(!$name||!$contact||!$service||mb_strlen($description)<10||empty($body['consent']))bad('Заполните поля, опишите задачу (от 10 символов) и подтвердите согласие');$id=uid();query('INSERT INTO leads(id,user_id,name,contact,service,description,created) VALUES (?,?,?,?,?,?,?)',[$id,$user['id']??null,$name,$contact,$service,$description,stamp()]);reply(['id'=>$id]);}
 if($path==='/api/leads'&&$method==='GET'){signedin();reply(['leads'=>$user['role']==='admin'?many('SELECT * FROM leads ORDER BY created DESC'):many('SELECT * FROM leads WHERE user_id=? ORDER BY created DESC',[$user['id']])]);}
