  if(isset($m[2])){if($method==='GET')reply(['messages'=>many('SELECT m.id,m.text,m.created,u.name,u.role FROM messages m JOIN users u ON u.id=m.user_id WHERE m.lead_id=? ORDER BY m.created',[$lead['id']])]);if($method==='POST'){$value=txt($body['text']??'',3000);if(!$value)bad('Сообщение пустое');query('INSERT INTO messages(id,lead_id,user_id,text,created) VALUES (?,?,?,?,?)',[uid(),$lead['id'],$user['id'],$value,stamp()]);reply(['ok'=>true]);}}
  if($method==='PATCH'){admin();$statuses=['Заявка получена','Обсуждение','Подготовка предложения','Согласование договора','В работе','На проверке','Завершён','На сопровождении'];if(!in_array($body['status']??'',$statuses,true)||!is_int($body['price']??null)||$body['price']<0)bad('Проверьте статус и стоимость');query('UPDATE leads SET status=?,price=?,due=? WHERE id=?',[$body['status'],$body['price'],txt($body['due']??'',40),$lead['id']]);reply(['ok'=>true]);}
 }
 if($path==='/api/estimates'){admin();if($method==='GET')reply(['estimates'=>many('SELECT * FROM estimates ORDER BY created DESC')]);if($method==='POST'){if(!txt($body['title']??'',200)||!is_int($body['total']??null)||$body['total']<0)bad('Проверьте расчёт');query('INSERT INTO estimates(id,user_id,title,data,total,created) VALUES (?,?,?,?,?,?)',[uid(),$user['id'],txt($body['title'],200),json_encode($body['data']),$body['total'],stamp()]);reply(['ok'=>true]);}}
 if($path==='/api/profile'&&$method==='PUT'){signedin();$name=txt($body['name']??'',80);if(!$name)bad('Введите имя');query('UPDATE users SET name=? WHERE id=?',[$name,$user['id']]);reply(['ok'=>true]);}
 reply(['error'=>'Не найдено'],404);
}catch(Throwable $e){if(isset($db)&&$db->inTransaction())$db->rollBack();$code=$e->getCode();$known=is_int($code)&&$code>=400&&$code<=499;if(!$known)error_log('OVERTAKE API: '.$e->getMessage());reply(['error'=>$known?$e->getMessage():'Не удалось выполнить запрос. Попробуйте позже'],$known?$code:500);}
